export default AddProductForm;

import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ onLoginSuccess }) => {
    const [credentials, setCredentials] = useState({ username: '', password: '' });
    const [error, setError] = useState('');

    const handleLogin = (e) => {
        e.preventDefault();
        axios.post('http://localhost:8080/api/auth/login', credentials)
            .then(response => {
                onLoginSuccess(response.data); // Předáme data uživatele do App.jsx
                setError('');
            })
            .catch(err => {
                setError('Špatné jméno nebo heslo');
            });
    };

    return (
        <div className="card shadow-sm mx-auto" style={{maxWidth: '400px'}}>
            <div className="card-body">
                <h3 className="card-title text-center mb-4">Přihlášení</h3>
                {error && <div className="alert alert-danger">{error}</div>}
                <form onSubmit={handleLogin}>
                    <div className="mb-3">
                        <label className="form-label">Uživatelské jméno</label>
                        <input
                            type="text" className="form-control" required
                            onChange={e => setCredentials({...credentials, username: e.target.value})}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Heslo</label>
                        <input
                            type="password" className="form-control" required
                            onChange={e => setCredentials({...credentials, password: e.target.value})}
                        />
                    </div>
                    <button type="submit" className="btn btn-primary w-100">Přihlásit se</button>
                </form>
            </div>
        </div>
    );
};

export default Login;

import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ onLoginSuccess }) => {
    const [mode, setMode] = useState('login');
    const [credentials, setCredentials] = useState({ username: '', password: '' });
    const [registerData, setRegisterData] = useState({
        username: '',
        password: '',
        email: '',
        firstName: '',
        lastName: ''
    });
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const handleLogin = (e) => {
        e.preventDefault();
        setSuccess('');
        axios.post('http://localhost:8080/api/auth/login', credentials)
            .then(response => {
                onLoginSuccess(response.data); // Předáme data uživatele do App.jsx
                setError('');
            })
            .catch(err => {
                setError('Špatné jméno nebo heslo');
            });
    };

    const handleRegister = (e) => {
        e.preventDefault();
        setError('');
        axios.post('http://localhost:8080/api/auth/register', registerData)
            .then(response => {
                setSuccess('Registrace proběhla úspěšně.');
                onLoginSuccess(response.data);
            })
            .catch(err => {
                const message = err.response?.data || 'Registrace se nezdařila.';
                setError(message);
            });
    };

    return (
        <div className="card shadow-sm mx-auto" style={{maxWidth: '400px'}}>
            <div className="card-body">
                <div className="btn-group w-100 mb-3" role="group">
                    <button
                        type="button"
                        className={`btn ${mode === 'login' ? 'btn-primary' : 'btn-outline-primary'}`}
                        onClick={() => { setMode('login'); setError(''); setSuccess(''); }}
                    >
                        Přihlášení
                    </button>
                    <button
                        type="button"
                        className={`btn ${mode === 'register' ? 'btn-primary' : 'btn-outline-primary'}`}
                        onClick={() => { setMode('register'); setError(''); setSuccess(''); }}
                    >
                        Registrace
                    </button>
                </div>
                <h3 className="card-title text-center mb-4">
                    {mode === 'login' ? 'Přihlášení' : 'Registrace'}
                </h3>
                {error && <div className="alert alert-danger">{error}</div>}
                {success && <div className="alert alert-success">{success}</div>}

                {mode === 'login' ? (
                    <form onSubmit={handleLogin}>
                        <div className="mb-3">
                            <label className="form-label">Uživatelské jméno</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setCredentials({...credentials, username: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Heslo</label>
                            <input
                                type="password" className="form-control" required
                                onChange={e => setCredentials({...credentials, password: e.target.value})}
                            />
                        </div>
                        <button type="submit" className="btn btn-primary w-100">Přihlásit se</button>
                    </form>
                ) : (
                    <form onSubmit={handleRegister}>
                        <div className="mb-3">
                            <label className="form-label">Uživatelské jméno</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, username: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">E-mail</label>
                            <input
                                type="email" className="form-control" required
                                onChange={e => setRegisterData({...registerData, email: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Heslo</label>
                            <input
                                type="password" className="form-control" required
                                onChange={e => setRegisterData({...registerData, password: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Jméno</label>
                            <input
                                type="text" className="form-control"
                                onChange={e => setRegisterData({...registerData, firstName: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Příjmení</label>
                            <input
                                type="text" className="form-control"
                                onChange={e => setRegisterData({...registerData, lastName: e.target.value})}
                            />
                        </div>
                        <button type="submit" className="btn btn-primary w-100">Zaregistrovat se</button>
                    </form>
                )}
            </div>
        </div>
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ProductList = ({ user }) => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);

    const loadProducts = () => {
        axios.get('http://localhost:8080/api/products')
            .then(response => {
                setProducts(response.data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Chyba při komunikaci s backendem:', error);
                setLoading(false);
            });
    };

    useEffect(() => {
        loadProducts();
    }, []);

    const handleDelete = (id) => {
        if (!window.confirm('Opravdu chcete smazat tento produkt?')) return;
        axios.delete(`http://localhost:8080/api/products/${id}`)
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při mazání:', error));
    };

    if (loading) return <div className="text-center">Načítám produkty...</div>;

    return (
        <div className="row">
            {products.map(product => (
                <div key={product.id} className="col-md-4 mb-4">
                    <div className="card h-100 shadow-sm">
                        <img
                            src={product.imageUrl || "https://placehold.co/400x400?text=Bez+obrazku"}
                            className="card-img-top"
                            alt={product.name}
                        />
                        <div className="card-body">
                            <h5 className="card-title fw-bold">{product.name}</h5>
                            <p className="card-text text-muted small">{product.description}</p>
                            <div className="d-flex justify-content-between align-items-center mt-3">
                                <span className="h5 mb-0 text-success">
                                    {Number(product.price).toLocaleString('cs-CZ')} Kč
                                </span>
                                <button className="btn btn-outline-primary btn-sm">Detail</button>
                            </div>
                            {user?.role === 'ADMIN' && (
                                <button
                                    className="btn btn-danger btn-sm w-100 mt-2"
                                    onClick={() => handleDelete(product.id)}
                                >
                                     Smazat produkt
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
};

export default ProductList;

import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ProductList = ({ user }) => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [stockEdits, setStockEdits] = useState({});

    const loadProducts = () => {
        axios.get('http://localhost:8080/api/products')
            .then(response => {
                setProducts(response.data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Chyba při komunikaci s backendem:', error);
                setLoading(false);
            });
    };

    useEffect(() => {
        loadProducts();
    }, []);

    const handleDelete = (id) => {
        if (!window.confirm('Opravdu chcete smazat tento produkt?')) return;
        axios.delete(`http://localhost:8080/api/products/${id}`)
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při mazání:', error));
    };

    const handleStockChange = (id, value) => {
        setStockEdits(prev => ({ ...prev, [id]: value }));
    };

    const handleStockSave = (id) => {
        const stockQuantity = Number(stockEdits[id]);
        if (!Number.isInteger(stockQuantity) || stockQuantity < 0) {
            alert('Zadejte nezáporné celé číslo.');
            return;
        }
        axios.patch(`http://localhost:8080/api/products/${id}/stock`, { stockQuantity })
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při ukládání skladu:', error));
    };

    if (loading) return <div className="text-center">Načítám produkty...</div>;

    return (
        <div className="row">
            {products.map(product => (
                <div key={product.id} className="col-md-4 mb-4">
                    <div className="card h-100 shadow-sm">
                        <img
                            src={product.imageUrl || "https://placehold.co/400x400?text=Bez+obrazku"}
                            className="card-img-top"
                            alt={product.name}
                        />
                        <div className="card-body">
                            <h5 className="card-title fw-bold">{product.name}</h5>
                            <p className="card-text text-muted small">{product.description}</p>
                            <div className="d-flex justify-content-between align-items-center mt-3">
                                <span className="h5 mb-0 text-success">
                                    {Number(product.price).toLocaleString('cs-CZ')} Kč
                                </span>
                                <button className="btn btn-outline-primary btn-sm">Detail</button>
                            </div>
                            <div className="text-muted small mt-2">
                                Skladem: {product.stockQuantity ?? 0} ks
                            </div>
                            {user?.role === 'ADMIN' && (
                                <div className="mt-2">
                                    <div className="input-group input-group-sm">
                                        <input
                                            type="number"
                                            className="form-control"
                                            min="0"
                                            value={stockEdits[product.id] ?? product.stockQuantity ?? 0}
                                            onChange={e => handleStockChange(product.id, e.target.value)}
                                        />
                                        <button
                                            className="btn btn-outline-success"
                                            type="button"
                                            onClick={() => handleStockSave(product.id)}
                                        >
                                            Uložit sklad
                                        </button>
                                    </div>
                                </div>
                            )}
                            {user?.role === 'ADMIN' && (
                                <button
                                    className="btn btn-danger btn-sm w-100 mt-2"
                                    onClick={() => handleDelete(product.id)}
                                >
                                     Smazat produkt
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
};

export default ProductList;
